from pathlib import Path
import hashlib, json, os, subprocess, time, tempfile

ROOT = Path.cwd()
EVIDENCE = Path(os.environ['CDC_WORKER_EVIDENCE_ROOT'])
EVIDENCE.mkdir(parents=True, exist_ok=True)
assert hashlib.sha256(Path(__file__).read_bytes()).hexdigest() == os.environ['CDC_PAYLOAD_SHA256'], 'Pinned worker drift'
assert subprocess.check_output(['git', 'rev-parse', 'HEAD'], text=True).strip() == MANIFEST['source_base'], 'Source drift'
assert not subprocess.check_output(['git', 'status', '--porcelain'], text=True).strip(), 'Dirty writer checkout'
for relative, expected in MANIFEST['original_sha256'].items():
    target = ROOT / relative
    if expected is None:
        assert not target.exists(), f'Unexpected existing path: {relative}'
    else:
        assert hashlib.sha256(target.read_bytes()).hexdigest() == expected, f'Original content drift: {relative}'
for relative, content in FILES.items():
    target = ROOT / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')
    assert hashlib.sha256(target.read_bytes()).hexdigest() == MANIFEST['payload_sha256'][relative]
(EVIDENCE / 'payload-manifest.json').write_text(json.dumps(MANIFEST, indent=2) + '\n')

checks = []
environment = os.environ.copy()
build_root = Path(tempfile.mkdtemp(prefix='g-switcher-word-build-', dir=os.environ.get('RUNNER_TEMP')))
environment['CARGO_TARGET_DIR'] = str(build_root / 'cargo-target')

def check(label, argv, timeout=600):
    started = time.monotonic()
    print('WORD_VALIDATION_START ' + label, flush=True)
    with (EVIDENCE / (label + '.log')).open('w', encoding='utf-8') as output:
        process = subprocess.run(argv, cwd=ROOT, env=environment, stdout=output,
                                 stderr=subprocess.STDOUT, timeout=timeout)
    checks.append({'label': label, 'argv': argv, 'exit_code': process.returncode,
                   'elapsed_seconds': round(time.monotonic() - started, 3)})
    (EVIDENCE / 'checks.json').write_text(json.dumps(checks, indent=2) + '\n')
    print('WORD_VALIDATION_END ' + label + ' exit=' + str(process.returncode), flush=True)
    if process.returncode:
        print((EVIDENCE / (label + '.log')).read_text()[-16000:], flush=True)
        raise RuntimeError('Validation failed: ' + label)

check('format', ['rustfmt', '--edition', '2021', '--config', 'skip_children=true', *[p for p in MANIFEST['paths'] if p.endswith('.rs')]])
check('portable-cargo-library-tests', ['cargo', 'test', '--locked', '--lib'])
check('windows-typed-compile', ['cargo', 'check', '--locked', '--target',
                              'x86_64-pc-windows-gnu', '--all-targets'])
check('windows-clippy', ['cargo', 'clippy', '--locked', '--target',
                         'x86_64-pc-windows-gnu', '--all-targets', '--', '-D', 'warnings'])
check('whitespace', ['git', 'diff', '--check'])

status = subprocess.check_output(['git', 'status', '--porcelain', '--untracked-files=all'], text=True)
changed = {line[3:] for line in status.splitlines()}
assert changed == set(MANIFEST['paths']), ('Write scope mismatch', changed)
record_path = ROOT / 'docs/work-status/word-refusal-diagnostics-2026-10-08.json'
record = json.loads(record_path.read_text())
record.update({'managed_validation': checks, 'installed_word_latency_measured': False})
record_path.write_text(json.dumps(record, indent=2) + '\n')
subprocess.run(['git', 'config', 'user.name', 'G-switcher managed executor'], check=True)
subprocess.run(['git', 'config', 'user.email', 'g-switcher@example.invalid'], check=True)
subprocess.run(['git', 'add', '--', *MANIFEST['paths']], check=True)
subprocess.run(['git', 'diff', '--cached', '--check'], check=True)
assert set(subprocess.check_output(['git', 'diff', '--cached', '--name-only'], text=True).splitlines()) == set(MANIFEST['paths'])
subprocess.run(['git', 'commit', '-m', '[skip ci] diagnose Word mutation refusal and pending native calls'], check=True)
candidate = subprocess.check_output(['git', 'rev-parse', 'HEAD'], text=True).strip()
assert not subprocess.check_output(['git', 'status', '--porcelain'], text=True).strip()
result = {'source_base': MANIFEST['source_base'], 'result_commit': candidate,
          'changed_paths': MANIFEST['paths'], 'checks': checks,
          'rca_report_sha256': MANIFEST['rca_report_sha256'],
          'task_scope_complete': True, 'full_product_word_verdict': False,
          'output_ref': 'out:word-native-product-candidate',
          'evidence_ref': 'evidence:pinned-payload-and-worker-checks'}
(EVIDENCE / 'result.json').write_text(json.dumps(result, indent=2) + '\n')
print('WORD_PRODUCT_CANDIDATE ' + candidate, flush=True)
